using FallenForest.Cinematics;using FallenForest.Core;using FallenForest.Player;using UnityEngine;namespace FallenForest.World{public sealed class InvisibleBoundary:MonoBehaviour{[SerializeField]private EndSequence endSequence;[SerializeField]private Vector3 outwardDirection=Vector3.forward;public Vector3 OutwardDirection=>outwardDirection.sqrMagnitude>.001f?outwardDirection.normalized:transform.forward;public void Contact(PlayerMotor player,Vector3 contactPoint){if(player==null||GameProgress.Instance==null||!GameProgress.Instance.FinalRun)return;if(endSequence==null)endSequence=FindFirstObjectByType<EndSequence>();endSequence?.Begin(player,contactPoint,OutwardDirection);}}}
